  let cents = abs / 10000n;
  const rest = abs % 10000n;
  if (rest > 5000n || (rest === 5000n && cents % 2n === 1n)) cents += 1n;
  return fromCents(cents * sign);
}

/** Two-decimal amounts added up exactly, skipping 'n/a'. */
export function sumDue(dues: string[]): string {
  return fromCents(dues.filter((d) => d !== 'n/a').reduce((total, d) => total + toCents(d), 0n));
}

/** A person's due-total: the figures of their claims that count (each as shown on its row) added up;
 *  'n/a' when their grade today has no rate today (rateToday undefined), unless a claim that counts has a
 *  figure (settled, stated, or live at the grade in force on its date), then the figures there are added up. */
export function personDue(claims: Claim[], rateOnDate: (date: string) => string | undefined,
    rateToday: string | undefined, floor: string, late: Late): string {
  const counted = claims.filter(counts);
  const dues = counted.map((c) => claimDue(c, rateOnDate(c.date), floor, late));
  if (rateToday === undefined && dues.every((d) => d === 'n/a')) return 'n/a';
  return sumDue(dues);
}

/** What the late charge follows: the sheet's terms in days, its late percent (two decimals) and its today. */
export type Late = { terms: number; pct: string; today: string };

/** A claim's due: the one fixed when it was settled (its late charge frozen in), else its figure — the one its
 *  person's last statement bound it to, else live on its amount at the rate, raised to the sheet's floor when
 *  below it — with the late charge on that figure added on top. A correction (a negative amount) has no floor
 *  and no late charge. */
export function claimDue(claim: Claim, rate: string | undefined, floor: string, late: Late): string {
  if (claim.settledDue !== null) return claim.settledDue;
  const correction = toCents(claim.amount) < 0n;
  const figure = claim.statedDue ?? (correction ? dueOn(claim.amount, rate) : floored(dueOn(claim.amount, rate), floor));
  if (correction) return figure;
  return figure === 'n/a' ? figure : fromCents(toCents(figure) + toCents(lateCharge(claim, figure, late)));
}

const DAY_MS = 24 * 60 * 60 * 1000;

/** The late charge on a claim whose figure is `figure`: the late percent of it for every full 30 days the
 *  claim is overdue (past its due-by, on the sheet's today), rounded like a due; 0.00 when not overdue, or a
 *  correction (a negative amount). */
export function lateCharge(claim: Claim, figure: string, late: Late): string {
  if (!overdue(claim, late.terms, late.today) || toCents(claim.amount) < 0n) return '0.00';
  const days = Math.round((Date.parse(`${late.today}T00:00:00Z`) - Date.parse(`${dueBy(claim, late.terms)}T00:00:00Z`)) / DAY_MS);
  const periods = BigInt(Math.floor(days / 30));
  return dueOn(figure, fromCents(toCents(late.pct) * periods));
}

/** A live due raised to the floor when below it; 'n/a' stays 'n/a'. */
export function floored(due: string, floor: string): string {
  return due === 'n/a' || toCents(due) >= toCents(floor) ? due : fromCents(toCents(floor));
}

import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A sheet: its id and its today (ISO yyyy-mm-dd). */
export type Sheet = { id: string; today: string };

export const sheetKey = (sheetId: string) => ['sheet', sheetId, 'meta'] as const;

export function useSheet(sheetId: string) {
  return useQuery({
    queryKey: sheetKey(sheetId),
    queryFn: () => getJson<Sheet>(`/api/sheets/${encodeURIComponent(sheetId)}`),
  });
}

/**
 * The sheet's today — the date every date-dependent decision and every default date on the sheet
 * uses. Never read the real clock (`new Date()`) for these; use this instead. '' while loading.
 */
export function useSheetToday(sheetId: string): string {
  return useSheet(sheetId).data?.today ?? '';
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Late } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';

/** The sheet's settings: the clerk limit with two decimals ('' when there is none) and the floor with two
 *  decimals (a claim's live due is at least it), and the terms in days (a claim's due-by is its date plus them), and
 *  the late percent with two decimals (an overdue claim gains it, of its figure, every full 30 days). */
export type Settings = { clerkLimit: string; floor: string; terms: string; latePct: string };

export const settingsKey = (sheetId: string) => ['sheet', sheetId, 'settings'] as const;

/** The floor a sheet starts with. */
export const DEFAULT_FLOOR = '1.00';

/** The terms a sheet starts with, in days. */
export const DEFAULT_TERMS = '14';

/** The late percent a sheet starts with. */
export const DEFAULT_LATE_PCT = '0.00';

/** The sheet's settings as they are now. */
export function useSettings(sheetId: string) {
  return useQuery({
    queryKey: settingsKey(sheetId),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`),
  });
}

/** The sheet's floor in force (the starting floor while the settings load). */
export function useFloor(sheetId: string): string {
  return useSettings(sheetId).data?.floor ?? DEFAULT_FLOOR;
}

/** The sheet's terms in force, in days (the starting terms while the settings load). */
export function useTerms(sheetId: string): number {
  return Number(useSettings(sheetId).data?.terms ?? DEFAULT_TERMS);
}

/** What the late charge follows now: the terms, the late percent and the sheet's today. */
export function useLate(sheetId: string): Late {
  return { terms: useTerms(sheetId), pct: useSettings(sheetId).data?.latePct ?? DEFAULT_LATE_PCT, today: useSheetToday(sheetId) };
}
import { PersonRow } from '../../slots/defs/personRow';
import { SheetBody } from '../../slots/defs/sheet';
import { gradeOn, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { claimDue, rateOn, sumDue, useRates } from '../rates/rates';
import type { Late, Rate } from '../rates/rates';
import { useFloor, useLate } from '../settings/settings';
import { live, overdue, useClaims } from './claims';
import type { Claim } from './claims';

/** The overdue claims that count among these, with the due of each (as shown on its row). */
function overdueDues(claims: Claim[], people: Person[], rates: Rate[], late: Late, floor: string) {
  const byId = new Map(people.map((p) => [p.id, p]));
  return live(claims, people)
    .filter((c) => overdue(c, late.terms, late.today))
    .map((c) => claimDue(c, rateOn(rates, gradeOn(byId.get(c.personId), c.date), c.date), floor, late));
}

function useOverdue(sheetId: string, people: Person[], claims: Claim[]) {
  const rates = useRates(sheetId).data ?? [];
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const dues = overdueDues(claims, people, rates, late, floor);
  return { count: dues.length, total: sumDue(dues) };
}

/** A person's overdue count and overdue-total: the due of their overdue claims that count
 *  (late charges included) added up. */
function PersonOverdue({ sheetId, person }: { sheetId: string; user: string; person: Person }) {
  const claims = (useClaims(sheetId).data ?? []).filter((c) => c.personId === person.id);
  const { count, total } = useOverdue(sheetId, [person], claims);
  return (
    <>
      <td data-testid="person-overdue-count">{count}</td>
      <td data-testid="person-overdue-total">{total}</td>
    </>
  );
}

/** The sheet's overdue count and overdue-total: every person's added up. */
function OverdueTotal({ sheetId }: { sheetId: string; user: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const { count, total } = useOverdue(sheetId, people, claims);
  return (
    <p>
      Overdue <strong data-testid="rollup-overdue-count">{count}</strong> totalling{' '}
      <strong data-testid="rollup-overdue-total">{total}</strong>
    </p>
  );
}

export const contributions = [
  SheetBody.fill({ order: 22, Component: OverdueTotal }),
  PersonRow.fill({ order: 25, Component: PersonOverdue }),
];

